// Parse and validate input
const input = $input.first().json;
const body = input.body || input;

// Échecs de validation : statut 400 porté par error.http_status (lu par « Respond »).
if (typeof body.text !== 'string' || !body.text) {
  return [{
    json: {
      success: false,
      error: { code: 'MISSING_TEXT', message: 'text is required', http_status: 400 }
    }
  }];
}

if (!body.api_key) {
  return [{
    json: {
      success: false,
      error: { code: 'MISSING_API_KEY', message: 'api_key is required', http_status: 400 }
    }
  }];
}

const threshold = body.threshold || 10000;
const textLength = body.text.length;

// If text is short enough, no chunking needed
if (textLength <= threshold) {
  return [{
    json: {
      success: true,
      needsChunking: false,
      segments: [{ index: 0, text: body.text, char_count: textLength }],
      total_segments: 1
    }
  }];
}

return [{
  json: {
    jobId: body.job_id,
    text: body.text,
    textLength: textLength,
    threshold: threshold,
    apiKey: body.api_key,
    context: body.context || {},
    needsChunking: true
  }
}];

// Pré-découpe LOCALE du texte en unités numérotées (#504).
// Le modèle ne recopie plus le texte : il ne choisit que les unités qui OUVRENT un segment,
// et « Parse Chunks » taille les segments dans le texte ORIGINAL. Le texte entier est traité.
const p = $input.first().json;
const text = String(p.text);
const L = text.length;

const MAX_SEGMENT = 8000;   // taille maximale d'un segment rendu
const UNITE_MAX = 1200;     // au-delà, un paragraphe est redécoupé en phrases
const UNITE_CIBLE = 700;    // phrases consécutives regroupées jusqu'à cette taille
const EXTRAIT = 60;         // caractères montrés au début et à la fin de chaque unité

// Aucune frontière à l'intérieur d'une balise <…>.
const dansBalise = new Array(L + 1).fill(false);
for (const m of text.matchAll(/<[^<>]{0,2000}>/g)) {
  for (let i = m.index + 1; i < m.index + m[0].length; i++) dansBalise[i] = true;
}

// Frontière = position où commence l'unité suivante ; priorité : 3 structure, 2 fin de propos, 1 phrase, 0 espace.
const prio = new Map();
const poser = (pos, pr) => {
  if (pos <= 0 || pos >= L || dansBalise[pos]) return;
  if ((prio.get(pos) ?? -1) < pr) prio.set(pos, pr);
};
// 3 : sauts de ligne et <br> (les blancs qui suivent restent dans l'unité précédente)
for (const m of text.matchAll(/(?:\n|<br\s*\/?>)(?:\s|<br\s*\/?>)*/gi)) poser(m.index + m[0].length, 3);
// 3 : avant un titre ou un <b> / <strong>
for (const m of text.matchAll(/<(?:b|strong|h[1-6])(?:\s[^>]*)?>/gi)) poser(m.index, 3);
// 2 : fin de propos — « : », « ׃ », ע"כ ; 1 : fin de phrase — . ? ! ;
for (const m of text.matchAll(/(?:׃|:(?=\s|<|$)|ע["״]כ[.:]?(?=\s|<|$))[ \t]*/g)) poser(m.index + m[0].length, 2);
for (const m of text.matchAll(/[.?!;](?=\s|<|$)[ \t]*/g)) poser(m.index + m[0].length, 1);

const fortes = [...prio.entries()].filter(([, pr]) => pr === 3).map(([pos]) => pos).sort((a, b) => a - b);
const bornes = [0];
const priorites = [3];

// Découpe un paragraphe [a, b[ en unités.
function paragraphe(a, b) {
  if (b - a <= UNITE_MAX) { bornes.push(b); priorites.push(prio.get(b) ?? 3); return; }
  const internes = [];
  for (let i = a + 1; i < b; i++) { const pr = prio.get(i); if (pr === 1 || pr === 2) internes.push(i); }
  let debut = a, fin = a;
  const fermer = (pos) => { bornes.push(pos); priorites.push(pos === b ? (prio.get(b) ?? 3) : prio.get(pos)); debut = pos; };
  for (const pos of internes.concat([b])) {
    if (pos - debut > UNITE_CIBLE && fin > debut) fermer(fin);
    fin = pos;
  }
  if (fin > debut) fermer(fin);
}
let prec = 0;
for (const pos of fortes) { paragraphe(prec, pos); prec = pos; }
paragraphe(prec, L);
priorites[priorites.length - 1] = 3;

// Une unité > MAX_SEGMENT sans frontière : coupée sur la dernière espace possible (sinon net, hors paire UTF-16).
for (let k = 0; k < bornes.length - 1; k++) {
  const a = bornes[k], b = bornes[k + 1];
  if (b - a <= MAX_SEGMENT) continue;
  let cut = -1;
  for (let i = a + MAX_SEGMENT; i > a; i--) {
    if (/\s/.test(text[i - 1]) && !dansBalise[i]) { cut = i; break; }
  }
  if (cut < 0) {
    cut = a + MAX_SEGMENT;
    const c = text.charCodeAt(cut - 1);
    if (c >= 0xD800 && c <= 0xDBFF) cut--;
  }
  bornes.splice(k + 1, 0, cut);
  priorites.splice(k + 1, 0, 0);
}

const n = bornes.length - 1;
const plat = (s) => s.replace(/\s+/g, ' ');
const lignes = [];
for (let k = 0; k < n; k++) {
  const u = text.slice(bornes[k], bornes[k + 1]);
  const vue = u.length <= 2 * EXTRAIT + 10
    ? plat(u).trim()
    : plat(u.slice(0, EXTRAIT)).trim() + ' […] ' + plat(u.slice(-EXTRAIT)).trim();
  lignes.push(`#${k} fin=${bornes[k + 1]} | ${vue}`);
}

const consigne = [
  'Tu es expert en textes hébraïques rabbiniques (Talmud, Kabbale, Zohar).',
  '',
  `Le texte ci-dessous (${L} caractères) a été pré-découpé en ${n} unités numérotées de 0 à ${n - 1}, dans l'ordre (paragraphes ou phrases).`,
  'Chaque ligne donne : le numéro de l\'unité, « fin » = position de sa fin dans le texte complet, puis son début et sa fin (« […] » marque la partie omise).',
  '',
  `Le texte sera découpé en segments d'au plus ${MAX_SEGMENT} caractères, et seulement au début d'une unité que tu désignes.`,
  'Indique les numéros de TOUTES les unités qui ouvrent un nouveau propos, là où une coupe est naturelle :',
  '- après une fin de citation (וכו\', ע"כ) ou la fin d\'un commentaire ;',
  '- au changement de sujet ou de commentateur ;',
  '- à un marqueur structurel (<b>, titre, saut de paragraphe).',
  'Jamais une unité qui continue une phrase commencée. Ignore les balises <img>.',
  `Il en faut assez pour que deux débuts consécutifs ne soient jamais distants de plus de ${MAX_SEGMENT} caractères (compare les « fin ») ; dans le doute, inclus l'unité : c'est le workflow qui choisit parmi tes débuts.`,
  '',
  'Réponds uniquement par le JSON {"debuts": [...]} : numéros croissants, le premier vaut 0.',
  '',
  'UNITÉS :',
  lignes.join('\n'),
  `FIN DU TEXTE : ${L}`,
].join('\n');

return [{
  json: {
    apiKey: p.apiKey,
    max_segment: MAX_SEGMENT,
    bornes,
    priorites,
    total_unites: n,
    corps_anthropic: {
      model: 'claude-haiku-4-5-20251001',
      max_tokens: 4096,
      temperature: 0,
      output_config: {
        format: {
          type: 'json_schema',
          schema: {
            type: 'object',
            properties: { debuts: { type: 'array', items: { type: 'integer' } } },
            required: ['debuts'],
            additionalProperties: false,
          },
        },
      },
      messages: [{ role: 'user', content: consigne }],
    },
  },
}];

// Segments taillés dans le texte ORIGINAL (#504) : coupes du modèle si elles sont valides,
// sinon repli déterministe. L'invariant (concaténation === texte) est vérifié AVANT de répondre.
const rep = $input.first().json;          // enveloppe fullResponse + neverError
const prep = $('Prepare Split').first().json;
const text = String($('Parse Input').first().json.text);
const bornes = prep.bornes;
const priorites = prep.priorites;
const MAX = prep.max_segment;
const n = bornes.length - 1;

const echec = (code, message) => [{ json: { success: false, error: { code, message, http_status: 500 } } }];

// Bornes saines, sinon rien à découper de fiable.
let bornesOk = Array.isArray(bornes) && n >= 1 && bornes[0] === 0 && bornes[n] === text.length;
for (let k = 0; bornesOk && k < n; k++) {
  if (!(bornes[k + 1] > bornes[k]) || bornes[k + 1] - bornes[k] > MAX) bornesOk = false;
}
if (!bornesOk) return echec('INVARIANT_VIOLATION', 'Pre-decoupage incoherent, aucun segment rendu');

// 1. Coupes proposées par le modèle — ou la raison de les écarter.
function coupesDuModele() {
  if (!rep || typeof rep !== 'object') return { raison: 'reponse_vide' };
  let body = rep.body;
  if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { return { raison: 'reponse_non_json' }; } }
  const statut = Number(rep.statusCode) || 0;
  if (!body) return { raison: rep.error ? 'appel_echoue' : 'reponse_vide' };
  if (body.type === 'error' || body.error || statut >= 300) {
    return { raison: 'erreur_anthropic_' + (statut || (body.error && body.error.type) || 'inconnue') };
  }
  const brut = (Array.isArray(body.content) ? body.content : [])
    .filter((b) => b && b.type === 'text').map((b) => b.text).join('').trim();
  if (!brut) return { raison: 'reponse_vide' };
  let parsed;
  try {
    const bloc = brut.match(/\{[\s\S]*\}/);
    parsed = JSON.parse(bloc ? bloc[0] : brut);
  } catch (e) { return { raison: body.stop_reason === 'max_tokens' ? 'reponse_tronquee' : 'json_invalide' }; }
  const d = parsed && parsed.debuts;
  if (!Array.isArray(d) || !d.length) return { raison: 'coupes_absentes' };
  if (!d.every((x) => Number.isInteger(x))) return { raison: 'coupes_non_entieres' };
  if (d.some((x) => x < 0 || x >= n)) return { raison: 'coupes_hors_bornes' };
  for (let k = 1; k < d.length; k++) if (d[k] <= d[k - 1]) return { raison: 'coupes_non_croissantes' };
  // Les débuts rendus sont des coupes AUTORISÉES (mesuré : le modèle ne sait pas sommer des longueurs
  // sur 200 unités) ; le choix parmi elles est local, par la même règle que le repli.
  const debuts = empaqueter(d[0] === 0 ? d : [0].concat(d));
  return debuts ? { debuts } : { raison: 'segment_trop_long' };
}

// 2. Empaquetage glouton sur des débuts candidats (numéros d'unités croissants, le premier 0) :
//    depuis chaque début, parmi les candidats qui tiennent dans MAX, la frontière la plus forte
//    laissant au moins MAX/2, la plus lointaine à égalité. null si deux candidats consécutifs
//    sont distants de plus de MAX. Repli déterministe = empaquetage sur TOUTES les unités.
function empaqueter(cands) {
  const debuts = [0];
  let i = 0;
  while (bornes[n] - bornes[cands[i]] > MAX) {
    let meilleur = -1, meilleurePrio = -2;
    for (let j = i + 1; j < cands.length && bornes[cands[j]] - bornes[cands[i]] <= MAX; j++) {
      const pr = bornes[cands[j]] - bornes[cands[i]] >= MAX / 2 ? priorites[cands[j]] : -1;
      if (pr >= meilleurePrio) { meilleur = j; meilleurePrio = pr; }
    }
    if (meilleur < 0) return null;
    debuts.push(cands[meilleur]);
    i = meilleur;
  }
  return debuts;
}

const modele = coupesDuModele();
const method = modele.debuts ? 'claude_boundaries' : 'deterministic_fallback';
const debuts = modele.debuts || empaqueter(Array.from({ length: n }, (_, k) => k));

const segments = debuts.map((d, k) => {
  const t = text.slice(bornes[d], bornes[k + 1 < debuts.length ? debuts[k + 1] : n]);
  return { index: k, text: t, char_count: t.length };
});

// 3. Invariant absolu, vérifié ici : sinon échec explicite, jamais un succès.
const casse = segments.map((s) => s.text).join('') !== text
  || segments.some((s, k) => s.index !== k || s.char_count !== s.text.length || s.char_count === 0 || s.char_count > MAX);
if (casse) return echec('INVARIANT_VIOLATION', 'Les segments ne reconstituent pas le texte a l identique');

const out = { success: true, segments, total_segments: segments.length, method };
if (!modele.debuts) out.fallback_reason = modele.raison;
return [{ json: out }];

// Parse and validate input
const input = $input.first().json;
const body = input.body || input;

if (!body.text) {
  return [{
    json: {
      success: false,
      error: { code: 'MISSING_TEXT', message: 'text is required' }
    }
  }];
}

if (!body.api_key) {
  return [{
    json: {
      success: false,
      error: { code: 'MISSING_API_KEY', message: 'api_key is required' }
    }
  }];
}

const threshold = body.threshold || 10000;
const textLength = body.text.length;

// If text is short enough, no chunking needed
if (textLength <= threshold) {
  return [{
    json: {
      success: true,
      needsChunking: false,
      segments: [{ index: 0, text: body.text, char_count: textLength }],
      total_segments: 1
    }
  }];
}

return [{
  json: {
    jobId: body.job_id,
    text: body.text,
    textLength: textLength,
    threshold: threshold,
    apiKey: body.api_key,
    context: body.context || {},
    needsChunking: true
  }
}];

// Parse Claude's chunking response
const input = $input.first().json;
const prevData = $('Parse Input').first().json;

try {
  const body = input.body || input;

  // Check for API error
  if (body.error) {
    return [{
      json: {
        success: false,
        error: {
          code: 'CLAUDE_ERROR',
          message: body.error.message || 'Smart Split API error'
        }
      }
    }];
  }

  const content = body.content?.[0]?.text || '';

  if (!content) {
    return [{
      json: {
        success: false,
        error: {
          code: 'EMPTY_RESPONSE',
          message: 'Smart Split returned empty response'
        }
      }
    }];
  }

  // Try to parse JSON from response
  let jsonStr = content;
  const jsonMatch = content.match(/```json\n?([\s\S]*?)\n?```/);
  if (jsonMatch) {
    jsonStr = jsonMatch[1];
  }

  const parsed = JSON.parse(jsonStr);
  const chunks = parsed.chunks || [];

  if (chunks.length === 0) {
    return [{
      json: {
        success: false,
        error: {
          code: 'NO_CHUNKS',
          message: 'Smart Split returned no chunks'
        }
      }
    }];
  }

  // Format segments
  const segments = chunks.map((chunk, idx) => ({
    index: chunk.index !== undefined ? chunk.index : idx,
    text: chunk.text,
    char_count: chunk.char_count || chunk.text.length
  }));

  return [{
    json: {
      success: true,
      segments: segments,
      total_segments: segments.length,
      method: 'claude_semantic'
    }
  }];
} catch (e) {
  return [{
    json: {
      success: false,
      error: {
        code: 'PARSE_ERROR',
        message: 'Failed to parse Smart Split response: ' + e.message
      }
    }
  }];
}
